 46	const SCHEMA: &str = "k6-observe-v1";
 47	/// `--allow-over-estimate` is accepted only under a heap cap this small.
 48	const OVER_ESTIMATE_CAP_LIMIT: usize = 512 * 1024 * 1024;
 49	/// Bitwise K is recorded up to this member count (K6 brief Scope 7).
 50	const BITWISE_K_MEMBERS: usize = 1000;
 51	
 52	// ------------------------------------------------------------------ output
 53	
 54	/// One JSON object, keys in insertion order.
 55	struct Line(String);
 56	
 57	impl Line {
 58	    fn new(kind: &str) -> Self {
 59	        let mut line = Line(String::from("{"));
 60	        line.key("kind");
 61	        line.quoted(kind);
 62	        line
 63	    }
 64	    fn key(&mut self, key: &str) {
 65	        if self.0.len() > 1 {
 66	            self.0.push(',');
 67	        }
 68	        self.quoted(key);
 69	        self.0.push(':');
 70	    }
 71	    fn quoted(&mut self, text: &str) {
 72	        self.0.push('"');
 73	        for c in text.chars() {
 74	            match c {
 75	                '"' => self.0.push_str("\\\""),
 76	                '\\' => self.0.push_str("\\\\"),
 77	                '\n' => self.0.push_str("\\n"),
 78	                '\r' => self.0.push_str("\\r"),
 79	                '\t' => self.0.push_str("\\t"),
 80	                c if (c as u32) < 0x20 => self.0.push_str(&format!("\\u{:04x}", c as u32)),
 81	                c => self.0.push(c),
 82	            }
 83	        }
 84	        self.0.push('"');
 85	    }
 86	    fn s(mut self, key: &str, value: &str) -> Self {
 87	        self.key(key);
 88	        self.quoted(value);
 89	        self
 90	    }
 91	    fn n(mut self, key: &str, value: impl Display) -> Self {
 92	        self.key(key);
 93	        self.0.push_str(&value.to_string());
 94	        self
 95	    }
 96	    fn b(mut self, key: &str, value: bool) -> Self {
 97	        self.key(key);
 98	        self.0.push_str(if value { "true" } else { "false" });
 99	        self
100	    }
101	    fn opt_s(self, key: &str, value: Option<&str>) -> Self {
102	        match value {
103	            Some(v) => self.s(key, v),
104	            None => self.null(key),
105	        }
106	    }
107	    fn opt_n(self, key: &str, value: Option<impl Display>) -> Self {
108	        match value {
109	            Some(v) => self.n(key, v),
110	            None => self.null(key),
111	        }
112	    }
113	    fn null(mut self, key: &str) -> Self {
114	        self.key(key);
115	        self.0.push_str("null");
116	        self
117	    }
118	    fn hex(self, key: &str, value: u64) -> Self {
119	        self.s(key, &format!("{value:016x}"))
120	    }
121	    /// A binary64 in exponent form (the shortest round-trip digits), `null`
122	    /// when absent, and a string for a non-finite value (not a JSON number).
123	    fn f(mut self, key: &str, value: Option<f64>) -> Self {
124	        match value {
125	            None => self.null(key),
126	            Some(x) if x.is_finite() => {
127	                self.key(key);
128	                self.0.push_str(&format!("{x:e}"));
129	                self
130	            }
131	            Some(x) => self.s(key, &format!("{x}")),
132	        }
133	    }
134	    fn emit(mut self) {
135	        self.0.push('}');
136	        self.0.push('\n');
137	        let mut out = std::io::stdout().lock();
138	        let _ = out.write_all(self.0.as_bytes());
139	        let _ = out.flush();
140	    }
141	}
