170	fn usage(message: &str) -> ! {
171	    eprintln!("k6_observe: {message}");
172	    eprintln!(
173	        "usage: k6_observe (--model <id> | --model-file <path>) --mode sparse|dense|lane-id|lane-lu \
174	         --heap-cap-bytes <n> [--repeats 5] [--entry-repeats <k>] [--time-budget-s <s>] \
175	         [--first-repeat-limit-s 600] [--counts-file <path>] [--dump-solution <path>] [--allow-over-estimate]\n       \
176	         k6_observe --emit-model --model <id>\n       \
177	         k6_observe --counts-only (--model <id> | --model-file <path>) --heap-cap-bytes <n> [--dump-pattern <path>]\n       \
178	         k6_observe --noop --heap-cap-bytes <n>\n       \
179	         k6_observe --list-models\n       \
180	         k6_observe (--model <id> | --model-file <path>) --mode w1a --heap-cap-bytes <n> [--repeats 5] \
181	         [--case-limit <u64>] [--invocation-limit <u64>] [--w1-prefixes] [--dump-published <path>] \
182	         [--counts-file <path>] [--time-budget-s <s>] [--first-repeat-limit-s 600]\n       \
183	         k6_observe --emit-source (--model <id> | --model-file <path>)"
184	    );
185	    std::process::exit(2)
186	}
187	
188	fn parse_args() -> Args {
189	    let mut args = Args {
190	        model: None,
191	        model_file: None,
192	        mode: None,
193	        heap_cap: None,
194	        repeats: 5,
195	        entry_repeats: None,
196	        time_budget_s: None,
197	        first_repeat_limit_s: 600,
198	        dump_solution: None,
199	        dump_pattern: None,
200	        counts_file: None,
201	        allow_over_estimate: false,
202	        emit_model: false,
203	        counts_only: false,
204	        noop: false,
205	        list_models: false,
206	        case_limit: u64::MAX,
207	        invocation_limit: u64::MAX,
208	        w1_prefixes: false,
209	        dump_published: None,
210	        emit_source: false,
211	    };
212	    let mut it = std::env::args().skip(1);
213	    while let Some(flag) = it.next() {
214	        let mut value = || {
215	            it.next()
216	                .unwrap_or_else(|| usage(&format!("{flag} needs a value")))
217	        };
218	        let number = |text: String| -> u64 {
219	            text.parse()
220	                .unwrap_or_else(|_| usage(&format!("not a number: {text}")))
221	        };
222	        match flag.as_str() {
223	            "--model" => args.model = Some(value()),
224	            "--model-file" => args.model_file = Some(value()),
225	            "--mode" => {
226	                let text = value();
227	                args.mode = Some(
228	                    Mode::parse(&text).unwrap_or_else(|| usage(&format!("unknown mode {text}"))),
229	                );
230	            }
231	            "--heap-cap-bytes" => args.heap_cap = Some(number(value()) as usize),
232	            "--repeats" => args.repeats = number(value()) as usize,
233	            "--entry-repeats" => args.entry_repeats = Some(number(value()) as usize),
234	            "--time-budget-s" => args.time_budget_s = Some(number(value())),
235	            "--first-repeat-limit-s" => args.first_repeat_limit_s = number(value()),
236	            "--dump-solution" => args.dump_solution = Some(value()),
237	            "--dump-pattern" => args.dump_pattern = Some(value()),
238	            "--counts-file" => args.counts_file = Some(value()),
239	            "--allow-over-estimate" => args.allow_over_estimate = true,
240	            "--emit-model" => args.emit_model = true,
241	            "--counts-only" => args.counts_only = true,
242	            "--noop" => args.noop = true,
243	            "--list-models" => args.list_models = true,
244	            "--case-limit" => args.case_limit = number(value()),
245	            "--invocation-limit" => args.invocation_limit = number(value()),
246	            "--w1-prefixes" => args.w1_prefixes = true,
247	            "--dump-published" => args.dump_published = Some(value()),
248	            "--emit-source" => args.emit_source = true,
249	            other => usage(&format!("unknown argument {other}")),
250	        }
251	    }
252	    args
253	}
254	
255	fn load_model(args: &Args) -> K6Model {
256	    match (&args.model, &args.model_file) {
257	        (Some(id), None) => model(id).unwrap_or_else(|e| usage(&e)),
258	        (None, Some(path)) => {
259	            let text = std::fs::read_to_string(path)
260	                .unwrap_or_else(|e| usage(&format!("cannot read the model file: {e}")));
261	            canonical::parse(&text).unwrap_or_else(|e| usage(&e))
262	        }
263	        _ => usage("give exactly one of --model and --model-file"),
264	    }
265	}
