267	// ------------------------------------------------------------------ observer
268	
269	struct Observer {
270	    repeat: usize,
271	    started: Option<Instant>,
272	    current_begin: usize,
273	    calls_begin: u64,
274	    /// The largest stage peaks seen (the repeats' peak, without the counts
275	    /// and parity phases).
276	    max_stage_peak: usize,
277	    max_stage_peak_move: usize,
278	}
279	
280	impl StageObserver for Observer {
281	    fn begin(&mut self, stage: Stage) {
282	        Line::new("stage_begin")
283	            .n("repeat", self.repeat)
284	            .s("stage", stage.as_str())
285	            .n("heap_current", alloc::current())
286	            .emit();
287	        alloc::stage_reset();
288	        self.current_begin = alloc::current();
289	        self.calls_begin = alloc::calls();
290	        self.started = Some(Instant::now());
291	    }
292	    fn end(&mut self, stage: Stage, ok: bool, error: Option<String>) {
293	        let elapsed = self
294	            .started
295	            .take()
296	            .map(|t| t.elapsed().as_nanos())
297	            .unwrap_or(0);
298	        let (peak, peak_move, current) = (
299	            alloc::stage_peak(),
300	            alloc::stage_peak_move(),
301	            alloc::current(),
302	        );
303	        let calls = alloc::calls() - self.calls_begin;
304	        self.max_stage_peak = self.max_stage_peak.max(peak);
305	        self.max_stage_peak_move = self.max_stage_peak_move.max(peak_move);
306	        Line::new("stage")
307	            .n("repeat", self.repeat)
308	            .s("stage", stage.as_str())
309	            .b("ok", ok)
310	            .n("elapsed_ns", elapsed)
311	            .n("heap_current_begin", self.current_begin)
312	            .n("heap_current_end", current)
313	            .n("heap_peak", peak)
314	            .n("heap_peak_move", peak_move)
315	            .n("alloc_calls", calls)
316	            .opt_s("error", error.as_deref())
317	            .emit();
318	    }
319	}
320	
321	// ------------------------------------------------------------------ phases
322	
323	fn refusal(reason: &str, estimate: Option<u128>) -> ! {
324	    Line::new("refusal")
325	        .s("reason", reason)
326	        .opt_n("estimate_adm_bytes", estimate)
327	        .n("heap_cap_bytes", alloc::cap())
328	        .n("heap_peak_so_far", alloc::peak())
329	        .n("heap_peak_move_so_far", alloc::peak_move())
330	        .emit();
331	    std::process::exit(3)
332	}
