334	/// The model's canonical length and FNV-1a digest, streamed.
335	fn canonical_digest(model: &K6Model) -> (u64, u64) {
336	    let mut digest = Fnv64::new();
337	    canonical::write_canonical(model, &mut digest);
338	    (digest.len(), digest.finish())
339	}
340	
341	fn counts_line(
342	    model: &K6Model,
343	    mode: Option<Mode>,
344	    c: &K6Counts,
345	    source: &str,
346	    phase: Option<(u128, usize, usize)>,
347	    w1_error: Option<&str>,
348	) {
349	    let sizes = SizeFacts::of_this_build();
350	    let (canonical_len, canonical_fnv) = canonical_digest(model);
351	    let mut line = Line::new("counts")
352	        .s("counts_source", source)
353	        .s("model", &model.id)
354	        .s("family", model.family.as_str())
355	        .n("nodes", c.nodes)
356	        .n("members", c.members)
357	        .n("dofs", c.dofs)
358	        .n("free_dofs", c.free_dofs)
359	        .n("restrained_dofs", c.restrained_dofs)
360	        .n("pattern_entries", c.pattern_entries)
361	        .n("lower_entries", c.lower_entries)
362	        .n("free_entries", c.free_entries)
363	        .n("free_lower_entries", c.free_lower_entries)
364	        .n("free_lower_nonzero", c.free_lower_nonzero)
365	        .n("rcm_profile_entries", c.rcm_profile_entries)
366	        .n("rcm_half_bandwidth", c.rcm_half_bandwidth)
367	        .n("identity_profile_entries", c.identity_profile_entries)
368	        .n("identity_half_bandwidth", c.identity_half_bandwidth)
369	        .n("lane_entries", c.lane_entries)
370	        .n("lane_off_diagonal", c.lane_off_diagonal)
371	        .n("contributions", c.contributions)
372	        .n("dense_entries", c.dense_entries);
373	    for m in [Mode::Sparse, Mode::Dense, Mode::LaneId, Mode::LaneLu] {
374	        line = line
375	            .opt_n(
376	                &format!("estimate_f1b_bytes_{}", m.as_str().replace('-', "_")),
377	                f1b_estimate_bytes(m, c),
378	            )
379	            .n(
380	                &format!("estimate_adm_bytes_{}", m.as_str().replace('-', "_")),
381	                admission_estimate_bytes(m, c, &sizes),
382	            );
383	    }
384	    // K6b: W1's counts, storage and estimate (plan §3.4, §3.5), when the
385	    // counts carry them.
386	    if let Some(w) = &c.w1 {
387	        let e = w1_estimate(w, &W1SizeFacts::of_this_build());
388	        line = line
389	            .null("estimate_f1b_bytes_w1a")
390	            .n("estimate_adm_bytes_w1a", e.max)
391	            .n("estimate_w1_sel128_bytes", e.sel128)
392	            .n("estimate_w1_fixed_bytes", e.fixed)
393	            .n("estimate_w1_decide_bytes", e.decide);
394	        for (k, &(p, _)) in LIMBS_PER_ENTRY.iter().enumerate() {
395	            line = line
396	                .n(&format!("estimate_w1_shared_{p}"), e.shared[k])
397	                .n(&format!("estimate_w1_state_{p}"), e.state[k])
398	                .n(&format!("estimate_w1_solve_{p}"), e.solve[k]);
399	        }
400	        for (k, p) in [256, 512, 1024].iter().enumerate() {
401	            line = line
402	                .n(&format!("estimate_w1_verify_{p}"), e.verify[k])
403	                .n(&format!("estimate_w1_pass_{p}"), e.pass[k]);
404	        }
405	        line = line
406	            .b("w1_source_ok", w.source_ok)
407	            .opt_s("w1_source_error", w1_error)
408	            .n("w1_nodes", w.nodes)
409	            .n("w1_members", w.members)
410	            .n("w1_stations", w.stations)
411	            .n("w1_constraints", w.constraints)
412	            .n("w1_loads", w.loads)
413	            .n("w1_dofs", w.dofs)
414	            .n("w1_free_dofs", w.free_dofs)
415	            .n("w1_bodies", w.bodies)
416	            .n("w1_pattern_entries", w.pattern_entries)
417	            .n("w1_profile_entries", w.profile_entries)
418	            .n("w1_half_bandwidth", w.half_bandwidth)
419	            .n("w1_blocks", w.blocks)
420	            .n("w1_rows", w.rows);
421	        for &(p, limbs) in &LIMBS_PER_ENTRY {
422	            line = line
423	                .n(&format!("w1_limbs_per_entry_{p}"), limbs)
424	                .n(&format!("w1_storage_bytes_{p}"), storage_bytes(w, p));
425	        }
426	        for limbs in [4u128, 8, 16] {
427	            line = line.n(&format!("w1_wide_bytes_{limbs}"), wide_bytes(limbs));
428	        }
429	        line = line
430	            .n("w1_source_encoding_len", w.source_encoding_len)

800	                    }
801	                }
802	            }
803	            Mode::LaneId | Mode::LaneLu => {
804	                let lane = if mode == Mode::LaneId {
805	                    lane_id(&model, &frames, &mut observer)
806	                } else {
807	                    lane_lu(&model, &frames, &mut observer)
808	                };
809	                match lane {
810	                    Err(error) => {
811	                        Line::new("outcome")
812	                            .n("repeat", repeat)
813	                            .s("class", "SetupError")
814	                            .s("failed_stage", error.stage.as_str())
815	                            .s("detail", &error.detail)
816	                            .emit();
817	                        internal_error = true;
818	                        (0, 0)
819	                    }
820	                    Ok(lane) => {
821	                        let mut line = Line::new("outcome")
822	                            .n("repeat", repeat)
823	                            .s("class", if lane.ok { "LaneSolved" } else { "LaneError" })
824	                            .opt_s("error", lane.error.as_deref())
825	                            .n("solution_len", lane.solution_len)
826	                            .hex("solution_fnv64", lane.solution_digest);
827	                        if let Some((original, ordered, original_bw, ordered_bw, entries)) =
828	                            lane.profile
829	                        {
830	                            line = line
831	                                .n("original_profile_entries", original)
832	                                .n("ordered_profile_entries", ordered)
833	                                .n("original_half_bandwidth", original_bw)
834	                                .n("ordered_half_bandwidth", ordered_bw)
835	                                .n("lane_entries", entries);
836	                        }
837	                        line.emit();
838	                        if let Some((original, _, original_bw, _, entries)) = lane.profile {
839	                            parity("lane_identity_profile_equals_count", repeat, {
840	                                original as u128 == counts.identity_profile_entries
841	                                    && original_bw == counts.identity_half_bandwidth
842	                                    && entries == counts.lane_entries
843	                            })
844	                            .emit();
845	                        }
846	                        (lane.solution_len as u64, lane.solution_digest)
847	                    }
848	                }
849	            }
850	            Mode::W1a => {
851	                let w1_counts = counts.w1.as_ref().expect("the w1a mode carries W1 counts");
852	                match w1_source(&model, &mut observer) {
853	                    Err(error) => {
854	                        Line::new("outcome")
855	                            .n("repeat", repeat)
856	                            .s("class", "SourceRefused")
857	                            .s("reason", &format!("{error:?}"))
858	                            .emit();
859	                        source_refused = true;
860	                        (0, 0)
861	                    }
862	                    Ok(source) => {
863	                        let solve = w1_solve(source, w1_limits, Stage::W1Solve, &mut observer);
864	                        w1::outcome_line(repeat, &solve);
865	                        w1::attempt_lines(repeat, attempts_of(&solve.outcome));
866	                        if repeat == 0 {
867	                            w1::parity_lines(repeat, w1_counts, &solve);
868	                            if let Some(path) = &args.dump_published {
869	                                w1::dump_rows(path, &model.id, &solve);
870	                            }
871	                        }
872	                        w1_last_attempts = Some(attempts_of(&solve.outcome).to_vec());
873	                        w1::repeat_digest(&solve)
874	                    }
875	                }
876	            }
877	        };
878	        repeats_completed += 1;
879	        match first_digest {
880	            None => first_digest = Some(digest),
881	            Some(first) => determinism &= first == digest,
882	        }
883	        if internal_error {
884	            stop_reason = Some("setup_error");
885	            break;
886	        }
887	        if source_refused {
888	            stop_reason = Some("source_refused");
889	            break;
890	        }
891	        let repeat_elapsed = repeat_started.elapsed();
892	        if repeat == 0 && repeat_elapsed.as_secs() >= args.first_repeat_limit_s {
893	            stop_reason = Some("first_repeat_over_limit");
894	            break;
895	        }
896	        if let Some(budget) = args.time_budget_s {
897	            let projected = run_started.elapsed() + repeat_elapsed;
898	            if repeat + 1 < args.repeats && projected.as_secs() >= budget {
899	                stop_reason = Some("time_budget");
900	                break;
