233	fn add_stages(a: &mut StageWork, b: &StageWork) {
234	    a.formation += b.formation;
235	    a.assembly += b.assembly;
236	    a.residual_formation += b.residual_formation;
237	    a.factor += b.factor;
238	    a.condition += b.condition;
239	    a.rhs += b.rhs;
240	    a.solve += b.solve;
241	    a.refinement += b.refinement;
242	    a.recovery += b.recovery;
243	    a.stop_rule += b.stop_rule;
244	    a.bounded_gate += b.bounded_gate;
245	    a.scale += b.scale;
246	    a.estimate += b.estimate;
247	    a.charge += b.charge;
248	    a.bound += b.bound;
249	    a.shift += b.shift;
250	    a.bounded_formation += b.bounded_formation;
251	    a.wide_formation += b.wide_formation;
252	    a.uc += b.uc;
253	}
