255	/// Each attempt's work filed under its own precision, ascending.
256	pub fn work_by_precision(attempts: &[AttemptRecord]) -> Vec<PrecisionWork> {
257	    let mut out: Vec<PrecisionWork> = Vec::new();
258	    for a in attempts {
259	        let entry = match out.iter().position(|w| w.precision == a.precision) {
260	            Some(k) => &mut out[k],
261	            None => {
262	                out.push(PrecisionWork {
263	                    precision: a.precision,
264	                    attempts: 0,
265	                    own: StageWork::default(),
266	                    shared: StageWork::default(),
267	                    own_total: 0,
268	                    shared_total: 0,
269	                });
270	                out.last_mut().expect("just pushed")
271	            }
272	        };
273	        entry.attempts += 1;
274	        add_stages(&mut entry.own, &a.stages);
275	        add_stages(&mut entry.shared, &a.shared_stages);
276	        entry.own_total = entry.own_total.saturating_add(own_total(a));
277	        entry.shared_total = entry.shared_total.saturating_add(shared_total(a));
278	    }
279	    out.sort_by_key(|w| w.precision);
280	    out
281	}
