328	/// Parity `w1_prefix_segments` for prefix j (1-based): the prefix call ended on
329	/// the case budget, and its first j segments equal the full call's (RV22-N3:
330	/// the binary's predicate, here so that it is tested).
331	pub fn prefix_matches(j: usize, full: &[AttemptRecord], prefix: &CaseOutcome) -> bool {
332	    let full_segments = segments(full);
333	    let own = segments(attempts_of(prefix));
334	    let budget_stop = matches!(
335	        prefix,
336	        CaseOutcome::Unresolved {
337	            reason: UnresolvedReason::Budget(_),
338	            ..
339	        }
340	    );
341	    budget_stop && own.len() >= j && full_segments.len() > j && own[..j] == full_segments[..j]
342	}
343	
344	/// The prefix limits: every segment's end but the last (the last is the full
345	/// call).
346	pub fn prefix_limits(attempts: &[AttemptRecord]) -> Vec<(String, u64)> {
347	    let segs = segments(attempts);
348	    segs.iter()
349	        .take(segs.len().saturating_sub(1))
350	        .map(|s| (s.label.clone(), s.end))
351	        .collect()
352	}

  1	//! K6b: the `w1a` mode's lines (T3 K6b plan §3.4; ROOT's rulings on I16's
  2	//! plan, Q2): the outcome, one `attempt` line per attempt (a new kind; K6's
  3	//! kinds keep their schema), the parity items, the rows dump and the prefix
  4	//! lines.
  5	//!
  6	//! ROOT's rulings on the K6B-S3 stop and on RV22's review: the outcome's
  7	//! per-precision work is the charged totals, and each attempt line carries the
  8	//! work it was charged that no stage records (`own_unstaged`,
  9	//! `shared_unstaged`; zero on completed builds) and whether that is none
 10	//! (`stages_complete`).
 11	
 12	use super::Line;
 13	use open_pipe_stress_frame_kernel::structural::retained_api::{
 14	    AttemptRecord, CaseOutcome, GateTest, UnresolvedReason,
 15	};
 16	use open_pipe_stress_solver_performance_harness::k6::w1::counts::{
 17	    fnv64, limbs_per_entry, W1Counts,
 18	};
 19	use open_pipe_stress_solver_performance_harness::k6::w1::rows::{class_counts, write_rows};
 20	use open_pipe_stress_solver_performance_harness::k6::w1::staged::{
 21	    attempts_of, charged_by, outcome_class, own_total, prefix_matches, stage_fields,
 22	    stages_complete, stages_equal_totals, unstaged, work_by_precision, work_closes, W1Solve,
 23	};
 24	use open_pipe_stress_solver_performance_harness::k6::{debug_digest, Fnv64};
 25	use std::io::Write;
 26	
 27	/// At most this many characters of a `Debug` reason are printed.
 28	const REASON_CHARS: usize = 240;
 29	
 30	fn bounded(text: String) -> String {
 31	    text.chars().take(REASON_CHARS).collect()
 32	}
 33	
 34	fn gate(g: &Option<GateTest>) -> Option<String> {
 35	    g.as_ref().map(|g| match g {
 36	        GateTest::Coalesced => "coalesced".to_string(),
 37	        GateTest::Bounded { state, evaluated } => format!("bounded:{state}/{evaluated}"),
 38	    })
 39	}
 40	
 41	/// Whether the call ended on a budget (a stop: the limits are `u64::MAX`).
 42	pub fn budget_reached(solve: &W1Solve) -> bool {
 43	    solve.exhausted
 44	        || matches!(
 45	            solve.outcome,
 46	            CaseOutcome::Unresolved {
 47	                reason: UnresolvedReason::Budget(_),
 48	                ..
 49	            }
 50	        )
 51	}
 52	
 53	/// The repeat's determinism digest: the publication's and the evidence's
 54	/// `Debug` digests (a selected case), or the outcome's (otherwise; it holds
 55	/// only the reason and the attempts), and the charged work, folded into one
 56	/// FNV-1a. The retained solve's caches are not formatted.
 57	pub fn repeat_digest(solve: &W1Solve) -> (u64, u64) {
 58	    let parts = match &solve.outcome {
 59	        CaseOutcome::Selected(s) => vec![debug_digest(s.publish()), debug_digest(s.evidence())],
 60	        other => vec![debug_digest(other)],
 61	    };
 62	    let mut h = Fnv64::new();
 63	    let mut len = 0;
 64	    for (l, f) in parts {
 65	        len += l;
 66	        h.update(&l.to_le_bytes());
 67	        h.update(&f.to_le_bytes());
 68	    }
 69	    h.update(&solve.charged.to_le_bytes());
 70	    (len, h.finish())
 71	}
 72	
 73	/// The outcome line of one repeat.
 74	pub fn outcome_line(repeat: usize, solve: &W1Solve) {
 75	    let attempts = attempts_of(&solve.outcome);
 76	    let mut line = Line::new("outcome")
 77	        .n("repeat", repeat)
 78	        .s("class", outcome_class(&solve.outcome));
 79	    line = match &solve.outcome {
 80	        CaseOutcome::Selected(s) => {
 81	            let publication = s.publish();
 82	            let evidence = s.evidence();
 83	            let counts = class_counts(publication);
 84	            let (pub_len, pub_fnv) = debug_digest(publication);
 85	            let (ev_len, ev_fnv) = debug_digest(evidence);
 86	            line.n("selected_precision", s.selected_precision())
 87	                .n("verification_precision", evidence.verification_precision)
 88	                .null("reason")
 89	                .n("rows", publication.rows.len())
 90	                .n("rows_relative_verified", counts[0])
 91	                .n("rows_absolute_verified", counts[1])
 92	                .n("rows_input_derived", counts[2])
 93	                .n("rows_unpublishable", counts[3])
 94	                .n("publication_debug_len", pub_len)
 95	                .hex("publication_fnv64", pub_fnv)
275	        j,
276	        prefix_matches(j, full, &solve.outcome),
277	    )
278	    .emit();
279	}

240	
241	/// Writes the selected publication's rows (`k6b-rows v1`).
242	pub fn dump_rows(path: &str, model_id: &str, solve: &W1Solve) {
243	    let CaseOutcome::Selected(s) = &solve.outcome else {
244	        return;
245	    };
246	    let file = std::fs::File::create(path).unwrap_or_else(|e| {
247	        eprintln!("k6_observe: cannot write the rows dump: {e}");
248	        std::process::exit(4)
249	    });
250	    let mut out = std::io::BufWriter::new(file);
251	    if write_rows(model_id, s.publish(), &mut out).is_err() || out.flush().is_err() {
252	        eprintln!("k6_observe: cannot write the rows dump");
253	        std::process::exit(4);
254	    }
255	}
256	
257	/// The line of one prefix call (`prefix`, a new kind): its limit and segment,
258	/// its outcome, and whether its completed segments equal the full call's.
259	pub fn prefix_line(j: usize, label: &str, limit: u64, full: &[AttemptRecord], solve: &W1Solve) {
260	    let reason = match &solve.outcome {
261	        CaseOutcome::Unresolved { reason, .. } => Some(bounded(format!("{reason:?}"))),
262	        _ => None,
263	    };
264	    Line::new("prefix")
265	        .n("prefix", j)
266	        .s("through_segment", label)
267	        .n("case_limit", limit)
268	        .s("class", outcome_class(&solve.outcome))
269	        .opt_s("reason", reason.as_deref())
270	        .n("attempts", attempts_of(&solve.outcome).len())
271	        .n("meter_charged", solve.charged)
272	        .emit();
273	    parity(
274	        "w1_prefix_segments",
275	        j,
276	        prefix_matches(j, full, &solve.outcome),
277	    )
278	    .emit();
279	}

